// @ts-nocheck
const http = require('node:http');
const process = require('node:process');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || 'local-dev-key';

function jsonResponse(res, status, body) {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(data),
  });
  res.end(data);
}

function readJson(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.setEncoding('utf8');
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 1e7) {
        reject(new Error('payload too large'));
        req.destroy();
      }
    });
    req.on('end', () => {
      try {
        resolve(raw ? JSON.parse(raw) : null);
      } catch {
        reject(new Error('invalid json'));
      }
    });
    req.on('error', reject);
  });
}

function isNonBlankString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

const SECTORS = new Set(['energy', 'mining', 'water', 'transport', 'oil_and_gas', 'ict']);
const STAGES = new Set(['idea', 'feasibility', 'tender', 'financing', 'construction', 'operation', 'cancelled']);
const ROLES = new Set(['owner', 'developer', 'epc_contractor', 'financier', 'consultant']);

function validateKeyDate(x) {
  return x && typeof x === 'object' && !Array.isArray(x) &&
    Object.keys(x).length === 2 &&
    isNonBlankString(x.label) &&
    typeof x.date === 'string' &&
    /^\d{4}-\d{2}-\d{2}$/.test(x.date) &&
    !Number.isNaN(Date.parse(`${x.date}T00:00:00Z`)) &&
    new Date(`${x.date}T00:00:00Z`).toISOString().slice(0, 10) === x.date;
}

function validateEditableFields(x) {
  if (!x || typeof x !== 'object' || Array.isArray(x)) return false;
  const keys = Object.keys(x);
  const allowed = ['name', 'sector', 'country', 'stage', 'key_dates'];
  if (keys.length !== allowed.length) return false;
  for (const k of allowed) if (!keys.includes(k)) return false;
  return isNonBlankString(x.name) &&
    SECTORS.has(x.sector) &&
    isNonBlankString(x.country) &&
    STAGES.has(x.stage) &&
    Array.isArray(x.key_dates) &&
    x.key_dates.every(validateKeyDate);
}

function validateSaveRequest(x) {
  return x && typeof x === 'object' && !Array.isArray(x) &&
    Object.keys(x).length === 2 &&
    validateEditableFields(x.base) &&
    validateEditableFields(x.proposed);
}

function validateProjectDetail(x) {
  return validateEditableFields(x) && isNonBlankString(x.id);
}

function toSummary(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
  };
}

function toDetail(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
    key_dates: project.key_dates,
  };
}

function parseUpstreamProject(x) {
  if (!x || typeof x !== 'object' || Array.isArray(x)) return null;
  if (!isNonBlankString(x.id) || !isNonBlankString(x.name) || !SECTORS.has(x.sector) || !isNonBlankString(x.country) || !STAGES.has(x.stage) || !Array.isArray(x.key_dates) || !Array.isArray(x.linked_companies)) return null;
  const key_dates = x.key_dates.map((d) => ({ label: String(d.label), date: String(d.date) }));
  const linked_companies = x.linked_companies.map((c) => ({ name: String(c.name), role: String(c.role) }));
  return {
    id: x.id,
    name: x.name,
    sector: x.sector,
    country: x.country,
    stage: x.stage,
    key_dates,
    linked_companies,
  };
}

async function upstreamFetch(path, options = {}) {
  const headers = Object.assign({}, options.headers || {}, { 'X-Api-Key': UPSTREAM_API_KEY });
  return fetch(new URL(path, UPSTREAM_URL), { ...options, headers });
}

async function listProjects() {
  const res = await upstreamFetch('/projects');
  if (!res.ok) throw { kind: 'upstream', status: 502 };
  const json = await res.json();
  if (!Array.isArray(json)) throw { kind: 'upstream', status: 502 };
  const projects = [];
  for (const item of json) {
    const p = parseUpstreamProject(item);
    if (!p) throw { kind: 'upstream', status: 502 };
    projects.push(toSummary(p));
  }
  return projects;
}

async function getProject(projectId) {
  const res = await upstreamFetch(`/projects/${encodeURIComponent(projectId)}`);
  if (res.status === 404) throw { kind: 'notfound' };
  if (!res.ok) throw { kind: 'upstream', status: 502 };
  const json = await res.json();
  const p = parseUpstreamProject(json);
  if (!p || p.id !== projectId) throw { kind: 'upstream', status: 502 };
  return p;
}

function choose(base, proposed, current) {
  if (JSON.stringify(proposed) === JSON.stringify(base)) return { value: current, conflict: false };
  if (JSON.stringify(current) !== JSON.stringify(base) && JSON.stringify(current) !== JSON.stringify(proposed)) {
    return { value: current, conflict: true };
  }
  return { value: proposed, conflict: false };
}

function mergeEdit(base, proposed, current) {
  const n = choose(base.name, proposed.name, current.name);
  const s = choose(base.sector, proposed.sector, current.sector);
  const c = choose(base.country, proposed.country, current.country);
  const st = choose(base.stage, proposed.stage, current.stage);
  const k = choose(base.key_dates, proposed.key_dates, current.key_dates);
  const merged = {
    name: n.value,
    sector: s.value,
    country: c.value,
    stage: st.value,
    key_dates: k.value,
  };
  const conflicts = [];
  if (n.conflict) conflicts.push('name');
  if (s.conflict) conflicts.push('sector');
  if (c.conflict) conflicts.push('country');
  if (st.conflict) conflicts.push('stage');
  if (k.conflict) conflicts.push('key_dates');
  return { merged, conflicts, changed: JSON.stringify(merged) !== JSON.stringify(current) };
}

async function putProject(projectId, fields, linkedCompanies) {
  const body = {
    name: fields.name,
    sector: fields.sector,
    country: fields.country,
    stage: fields.stage,
    key_dates: fields.key_dates,
    linked_companies: linkedCompanies,
  };
  const res = await upstreamFetch(`/projects/${encodeURIComponent(projectId)}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (res.status === 404) throw { kind: 'notfound' };
  if (res.status === 504) throw { kind: 'uncertain' };
  if (!res.ok) throw { kind: 'upstream', status: 502 };
  const json = await res.json();
  const p = parseUpstreamProject(json);
  if (!p || p.id !== projectId) throw { kind: 'upstream', status: 502 };
  return p;
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
    if (!url.pathname.startsWith('/api/')) {
      jsonResponse(res, 404, { code: 'not_found' });
      return;
    }

    if (req.method === 'GET' && url.pathname === '/api/projects') {
      const projects = await listProjects();
      jsonResponse(res, 200, { projects });
      return;
    }

    const m = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
    if (req.method === 'GET' && m) {
      try {
        const project = await getProject(m[1]);
        jsonResponse(res, 200, { project: toDetail(project) });
      } catch (e) {
        if (e && e.kind === 'notfound') jsonResponse(res, 404, { code: 'project_not_found' });
        else jsonResponse(res, 502, { code: 'upstream_unavailable' });
      }
      return;
    }

    if (req.method === 'PUT' && m) {
      let body;
      try {
        body = await readJson(req);
      } catch {
        jsonResponse(res, 422, { code: 'validation_error' });
        return;
      }
      if (!validateSaveRequest(body)) {
        jsonResponse(res, 422, { code: 'validation_error' });
        return;
      }
      try {
        const current = await getProject(m[1]);
        const base = body.base;
        const proposed = body.proposed;
        const result = mergeEdit(base, proposed, current);
        if (result.conflicts.length) {
          jsonResponse(res, 409, { code: 'edit_conflict', current: toDetail(current), conflicting_fields: result.conflicts });
          return;
        }
        if (!result.changed) {
          jsonResponse(res, 200, { project: toDetail(current) });
          return;
        }
        try {
          const saved = await putProject(m[1], result.merged, current.linked_companies);
          jsonResponse(res, 200, { project: toDetail(saved) });
        } catch (e) {
          if (e && e.kind === 'uncertain') {
            let observed = null;
            try {
              observed = toDetail(await getProject(m[1]));
            } catch {}
            jsonResponse(res, 504, { code: 'write_uncertain', observed });
          } else if (e && e.kind === 'notfound') {
            jsonResponse(res, 404, { code: 'project_not_found' });
          } else {
            jsonResponse(res, 502, { code: 'upstream_unavailable' });
          }
        }
      } catch (e) {
        if (e && e.kind === 'notfound') jsonResponse(res, 404, { code: 'project_not_found' });
        else jsonResponse(res, 502, { code: 'upstream_unavailable' });
      }
      return;
    }

    jsonResponse(res, 404, { code: 'not_found' });
  } catch {
    jsonResponse(res, 502, { code: 'upstream_unavailable' });
  }
});

server.listen(PORT, '0.0.0.0');

// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || 'local-dev-key';

const SECTORS = new Set(['energy', 'mining', 'water', 'transport', 'oil_and_gas', 'ict']);
const STAGES = new Set(['idea', 'feasibility', 'tender', 'financing', 'construction', 'operation', 'cancelled']);
const COMPANY_ROLES = new Set(['owner', 'developer', 'epc_contractor', 'financier', 'consultant']);
const EDITABLE_FIELDS = ['name', 'sector', 'country', 'stage', 'key_dates'];

function json(res, status, body) {
  const data = Buffer.from(JSON.stringify(body));
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': String(data.length),
  });
  res.end(data);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.setEncoding('utf8');
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 1e6) {
        reject(new Error('body too large'));
        req.destroy();
      }
    });
    req.on('end', () => {
      if (!data) return resolve(null);
      try {
        resolve(JSON.parse(data));
      } catch {
        reject(new Error('invalid json'));
      }
    });
    req.on('error', reject);
  });
}

function isNonBlankString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

function parseISODate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const d = new Date(value + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return null;
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}` === value ? value : null;
}

function validateKeyDate(obj) {
  return obj && typeof obj === 'object' && !Array.isArray(obj) &&
    isNonBlankString(obj.label) && parseISODate(obj.date);
}

function validateEditableFields(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  const keys = Object.keys(obj);
  if (keys.length !== 5) return false;
  for (const k of EDITABLE_FIELDS) if (!Object.prototype.hasOwnProperty.call(obj, k)) return false;
  if (!isNonBlankString(obj.name)) return false;
  if (!SECTORS.has(obj.sector)) return false;
  if (!isNonBlankString(obj.country)) return false;
  if (!STAGES.has(obj.stage)) return false;
  if (!Array.isArray(obj.key_dates)) return false;
  if (!obj.key_dates.every(validateKeyDate)) return false;
  return true;
}

function validateProject(project) {
  return project && typeof project === 'object' &&
    typeof project.id === 'string' &&
    validateEditableFields(project);
}

function cloneProject(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
    key_dates: project.key_dates.map((d) => ({ label: d.label, date: d.date })),
  };
}

function summary(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
  };
}

function editableFields(project) {
  return {
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
    key_dates: project.key_dates.map((d) => ({ label: d.label, date: d.date })),
  };
}

function equalJson(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

function mergeEdit(base, proposed, current) {
  const merged = {};
  const conflicts = [];

  for (const field of EDITABLE_FIELDS) {
    const b = base[field];
    const p = proposed[field];
    const c = current[field];
    if (equalJson(p, b)) {
      merged[field] = cloneValue(c);
    } else if (!equalJson(c, b) && !equalJson(c, p)) {
      merged[field] = cloneValue(c);
      conflicts.push(field);
    } else {
      merged[field] = cloneValue(p);
    }
  }
  return { merged, conflicts, changed: !equalJson(merged, editableFields(current)) };
}

function cloneValue(v) {
  return Array.isArray(v) ? v.map((x) => ({ ...x })) : v;
}

async function upstreamFetch(path, options = {}) {
  const headers = { ...(options.headers || {}), 'X-Api-Key': UPSTREAM_API_KEY };
  const response = await fetch(new URL(path, UPSTREAM_URL), {
    ...options,
    headers,
  });
  return response;
}

async function upstreamReadJson(path) {
  const res = await upstreamFetch(path);
  if (!res.ok) {
    if (res.status === 404) {
      const err = new Error('project_not_found');
      err.code = 'project_not_found';
      throw err;
    }
    throw new Error('upstream_unavailable');
  }
  try {
    return await res.json();
  } catch {
    throw new Error('upstream_unavailable');
  }
}

async function listProjects() {
  const jsonBody = await upstreamReadJson('/projects');
  const projects = Array.isArray(jsonBody) ? jsonBody : [];
  return projects.filter(validateProject).map(summary);
}

async function getProject(id) {
  const jsonBody = await upstreamReadJson(`/projects/${encodeURIComponent(id)}`);
  if (!validateProject(jsonBody)) throw new Error('upstream_unavailable');
  return cloneProject(jsonBody);
}

async function putProject(id, fields, linkedCompanies) {
  const body = {
    name: fields.name,
    sector: fields.sector,
    country: fields.country,
    stage: fields.stage,
    key_dates: fields.key_dates.map((d) => ({ label: d.label, date: d.date })),
    linked_companies: linkedCompanies.map((c) => ({ name: c.name, role: c.role })),
  };
  const res = await upstreamFetch(`/projects/${encodeURIComponent(id)}`, {
    method: 'PUT',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (res.status === 404) {
    const err = new Error('project_not_found');
    err.code = 'project_not_found';
    throw err;
  }
  if (res.status === 504) {
    const err = new Error('write_uncertain');
    err.code = 'write_uncertain';
    throw err;
  }
  if (!res.ok) throw new Error('upstream_unavailable');
  const jsonBody = await res.json();
  if (!validateProject(jsonBody)) throw new Error('upstream_unavailable');
  return cloneProject(jsonBody);
}

function sendValidationError(res) {
  json(res, 422, { detail: 'Validation error' });
}

function parseId(url) {
  const m = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  return m ? decodeURIComponent(m[1]) : null;
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url || '/', 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/api/projects') {
      try {
        const projects = await listProjects();
        return json(res, 200, { projects });
      } catch (e) {
        if (e && e.code === 'project_not_found') return json(res, 404, { code: 'project_not_found' });
        return json(res, 502, { code: 'upstream_unavailable' });
      }
    }
    const projectId = parseId(url);
    if (req.method === 'GET' && projectId) {
      try {
        const project = await getProject(projectId);
        return json(res, 200, { project });
      } catch (e) {
        if (e && e.code === 'project_not_found') return json(res, 404, { code: 'project_not_found' });
        return json(res, 502, { code: 'upstream_unavailable' });
      }
    }
    if (req.method === 'PUT' && projectId) {
      let body;
      try {
        body = await readBody(req);
      } catch {
        return sendValidationError(res);
      }
      if (!body || typeof body !== 'object' || Array.isArray(body)) return sendValidationError(res);
      if (!Object.prototype.hasOwnProperty.call(body, 'base') || !Object.prototype.hasOwnProperty.call(body, 'proposed')) return sendValidationError(res);
      if (!validateEditableFields(body.base) || !validateEditableFields(body.proposed)) return sendValidationError(res);

      let current;
      try {
        current = await getProject(projectId);
      } catch (e) {
        if (e && e.code === 'project_not_found') return json(res, 404, { code: 'project_not_found' });
        return json(res, 502, { code: 'upstream_unavailable' });
      }

      const result = mergeEdit(body.base, body.proposed, editableFields(current));
      if (result.conflicts.length) {
        return json(res, 409, { code: 'edit_conflict', current, conflicting_fields: result.conflicts });
      }
      if (!result.changed) {
        return json(res, 200, { project: current });
      }

      try {
        const saved = await putProject(projectId, result.merged, current.linked_companies || []);
        return json(res, 200, { project: saved });
      } catch (e) {
        if (e && e.code === 'project_not_found') return json(res, 404, { code: 'project_not_found' });
        if (e && e.code === 'write_uncertain') {
          let observed = null;
          try {
            observed = await getProject(projectId);
          } catch (e2) {
            observed = null;
          }
          return json(res, 504, { code: 'write_uncertain', observed });
        }
        return json(res, 502, { code: 'upstream_unavailable' });
      }
    }

    res.writeHead(404, { 'content-type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ code: 'not_found' }));
  } catch {
    json(res, 500, { code: 'internal_error' });
  }
});

server.listen(PORT, '0.0.0.0');

// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || 'local-dev-key';

function json(res, status, body) {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(data),
  });
  res.end(data);
}

function send(res, status, code, extra) {
  json(res, status, Object.assign({ code }, extra || {}));
}

function isObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function validDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(s + 'T00:00:00.000Z');
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}

function validateKeyDate(v) {
  return isObj(v) && Object.keys(v).length === 2 && typeof v.label === 'string' && v.label.trim().length > 0 && validDate(v.date);
}

function validateEditable(v) {
  return (
    isObj(v) &&
    Object.keys(v).length === 5 &&
    typeof v.name === 'string' &&
    v.name.trim().length > 0 &&
    typeof v.country === 'string' &&
    v.country.trim().length > 0 &&
    ['energy', 'mining', 'water', 'transport', 'oil_and_gas', 'ict'].includes(v.sector) &&
    ['idea', 'feasibility', 'tender', 'financing', 'construction', 'operation', 'cancelled'].includes(v.stage) &&
    Array.isArray(v.key_dates) &&
    v.key_dates.every(validateKeyDate)
  );
}

function validateProject(v) {
  return isObj(v) && typeof v.id === 'string' && validateEditable(v);
}

function editableFields(project) {
  return {
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
    key_dates: Array.isArray(project.key_dates) ? project.key_dates.map((d) => ({ label: d.label, date: d.date })) : [],
  };
}

function projectSummary(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
  };
}

function projectDetail(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
    key_dates: Array.isArray(project.key_dates) ? project.key_dates.map((d) => ({ label: d.label, date: d.date })) : [],
  };
}

function conflictFields(base, proposed, current) {
  const fields = [];
  for (const key of ['name', 'sector', 'country', 'stage', 'key_dates']) {
    if (JSON.stringify(proposed[key]) === JSON.stringify(base[key])) continue;
    if (JSON.stringify(current[key]) !== JSON.stringify(base[key]) && JSON.stringify(current[key]) !== JSON.stringify(proposed[key])) {
      fields.push(key);
    }
  }
  return fields;
}

async function readJsonSafe(response) {
  try {
    return await response.json();
  } catch {
    return null;
  }
}

async function upstream(path, options) {
  const headers = Object.assign({ 'X-Api-Key': UPSTREAM_API_KEY }, options && options.headers ? options.headers : {});
  const res = await fetch(UPSTREAM_URL + path, Object.assign({}, options || {}, { headers }));
  const body = await readJsonSafe(res);
  return { res, body };
}

async function listProjects() {
  const { res, body } = await upstream('/projects', { method: 'GET' });
  if (!res.ok) return { error: true, status: 502 };
  if (!Array.isArray(body)) return { error: true, status: 502 };
  const projects = body.filter(validateProject).map(projectSummary);
  return { projects };
}

async function getProject(projectId) {
  const { res, body } = await upstream('/projects/' + encodeURIComponent(projectId), { method: 'GET' });
  if (res.status === 404) return { error: true, status: 404 };
  if (!res.ok || !validateProject(body)) return { error: true, status: 502 };
  return { project: projectDetail(body) };
}

async function handlePut(projectId, req, res) {
  const body = await new Promise((resolve) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 1e6) req.destroy();
    });
    req.on('end', () => {
      try {
        resolve(JSON.parse(raw || '{}'));
      } catch {
        resolve(null);
      }
    });
    req.on('error', () => resolve(null));
  });

  if (!isObj(body) || Object.keys(body).length !== 2 || !validateEditable(body.base) || !validateEditable(body.proposed)) {
    return send(res, 422, 'validation_error');
  }

  const currentResp = await upstream('/projects/' + encodeURIComponent(projectId), { method: 'GET' });
  if (currentResp.res.status === 404) return send(res, 404, 'project_not_found');
  if (!currentResp.res.ok || !validateProject(currentResp.body)) return send(res, 502, 'upstream_unavailable');
  const current = currentResp.body;

  const conflicts = conflictFields(body.base, body.proposed, editableFields(current));
  if (conflicts.length) {
    return json(res, 409, { code: 'edit_conflict', current: projectDetail(current), conflicting_fields: conflicts });
  }

  const merged = {
    name: body.base.name === body.proposed.name ? current.name : body.proposed.name,
    sector: body.base.sector === body.proposed.sector ? current.sector : body.proposed.sector,
    country: body.base.country === body.proposed.country ? current.country : body.proposed.country,
    stage: body.base.stage === body.proposed.stage ? current.stage : body.proposed.stage,
    key_dates: JSON.stringify(body.base.key_dates) === JSON.stringify(body.proposed.key_dates) ? current.key_dates : body.proposed.key_dates,
  };

  if (
    merged.name === current.name &&
    merged.sector === current.sector &&
    merged.country === current.country &&
    merged.stage === current.stage &&
    JSON.stringify(merged.key_dates) === JSON.stringify(current.key_dates)
  ) {
    return json(res, 200, { project: projectDetail(current) });
  }

  const putBody = {
    name: merged.name,
    sector: merged.sector,
    country: merged.country,
    stage: merged.stage,
    key_dates: merged.key_dates,
    linked_companies: Array.isArray(current.linked_companies) ? current.linked_companies : [],
  };

  const putResp = await upstream('/projects/' + encodeURIComponent(projectId), {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(putBody),
  });

  if (putResp.res.status === 404) return send(res, 404, 'project_not_found');
  if (putResp.res.status === 504) {
    let observed = null;
    const diag = await upstream('/projects/' + encodeURIComponent(projectId), { method: 'GET' });
    if (diag.res.ok && validateProject(diag.body)) observed = projectDetail(diag.body);
    return json(res, 504, { code: 'write_uncertain', observed });
  }
  if (!putResp.res.ok || !validateProject(putResp.body)) return send(res, 502, 'upstream_unavailable');
  return json(res, 200, { project: projectDetail(putResp.body) });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || '/', 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    const result = await listProjects();
    if (result.error) return send(res, result.status, result.status === 404 ? 'project_not_found' : 'upstream_unavailable');
    return json(res, 200, { projects: result.projects });
  }
  const match = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (req.method === 'GET' && match) {
    const result = await getProject(decodeURIComponent(match[1]));
    if (result.error) return send(res, result.status, result.status === 404 ? 'project_not_found' : 'upstream_unavailable');
    return json(res, 200, result);
  }
  if (req.method === 'PUT' && match) {
    return handlePut(decodeURIComponent(match[1]), req, res);
  }
  res.statusCode = 404;
  res.end('Not Found');
});

server.listen(PORT, '0.0.0.0');
